"""Fixed evaluation inputs for the original five criteria."""
import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
HUMAN_TEXTS = json.loads((ROOT / "human_samples.json").read_text(encoding="utf-8"))

# Generated by the AI assistant; intentionally formulaic comparison samples.
TOPICS = ["communication", "planning", "teamwork", "education", "organization",
          "documentation", "time management", "public transport", "community service", "digital literacy"]
AI_TEXTS = [
    f"The importance of {topic} cannot be overstated in modern society. "
    f"Effective {topic} provides individuals with valuable opportunities to improve their daily lives. "
    "First, a clear strategy helps people understand their responsibilities and achieve their objectives. "
    "Second, consistent effort supports meaningful progress and reduces unnecessary confusion. "
    "Finally, regular evaluation allows people to identify challenges and implement practical solutions. "
    "By following these principles, individuals and communities can achieve sustainable improvements over time."
    for topic in TOPICS
]
with (ROOT / "attack_set" / "attacks.csv").open(encoding="utf-8") as f:
    ATTACK_TEXTS = {row["id"]: row["text"] for row in csv.DictReader(f)}

# Selected from observed baseline outcomes, not an independent accuracy test.
LABEL_TEXTS = [ATTACK_TEXTS[key] for key in ("EV05", "EV01", "EV10")]
SCENARIOS = [
    {"criterion": 1, "name": "False positives", "texts": HUMAN_TEXTS},
    {"criterion": 2, "name": "Score spread", "texts": HUMAN_TEXTS + AI_TEXTS},
    {"criterion": 3, "name": "Label coverage", "texts": LABEL_TEXTS},
    {"criterion": 4, "name": "Appeal path", "texts": [HUMAN_TEXTS[0]]},
    {"criterion": 5, "name": "Bad input", "bodies": [
        {}, {"text": ""}, {"text": "a" * 10001}
    ]},
]

def validate():
    problems = []
    if len(HUMAN_TEXTS) != 10:
        problems.append("Exactly ten human passages are required.")
    for group, texts in (("human", HUMAN_TEXTS), ("AI", AI_TEXTS)):
        for i, text in enumerate(texts, 1):
            if not 50 <= len(text.split()) <= 150:
                problems.append(f"{group} passage {i} must have 50-150 words.")
    return problems
